"""Generate docs/api.md from the FastAPI OpenAPI schema so the docs cannot drift from the code.
Run from the project root with the venv active:  python scripts/gen_api_docs.py"""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "backend"))
from app.main import app  # noqa: E402

spec = app.openapi()
AUTH = ("/auth/register", "/auth/login", "/auth/logout", "/health", "/predictions", "/model/")
lines = [
    "# API reference (generated by `scripts/gen_api_docs.py`)", "",
    "Base path: `/api/v1`. Errors always use `{ \"error\": { \"code\", \"message\", \"details\" } }`.",
    "Private routes need the HttpOnly `access_token` cookie set by login or register; without it they return 401.",
    "Run the backend and open `/docs` for the interactive version (disabled when `APP_ENV=production`).", "",
    "| Method | Path | Summary | Auth |", "|---|---|---|---|",
]
for path, ops in spec["paths"].items():
    for method, op in ops.items():
        short = path.removeprefix("/api/v1")
        public = any(short.startswith(a) for a in AUTH)
        lines.append(f"| {method.upper()} | `{path}` | {op.get('summary', '')} | {'public' if public else 'cookie required'} |")
lines += ["", "## Request and response schemas", ""]
for name, sch in sorted(spec["components"]["schemas"].items()):
    if name in ("HTTPValidationError", "ValidationError"):
        continue
    lines.append(f"### {name}")
    req = set(sch.get("required", []))
    for prop, d in sch.get("properties", {}).items():
        bits = [d.get("type") or ("enum " + str(d["enum"]) if "enum" in d else "any")]
        if "enum" in d:
            bits = [f"one of {d['enum']}"]
        for k in ("minimum", "maximum", "minLength", "maxLength"):
            if k in d:
                bits.append(f"{k}={d[k]}")
        lines.append(f"- `{prop}`: {', '.join(map(str, bits))}{' (required)' if prop in req else ''}")
    lines.append("")
(ROOT / "docs" / "api.md").write_text("\n".join(lines), encoding="utf-8")
print("wrote docs/api.md with", sum(len(v) for v in spec["paths"].values()), "operations")
